/// `part` as a whole percentage of `total`, rounded down; 0 when `total` is 0.
pub fn percent(part: u64, total: u64) -> u64 {
    if total == 0 {
        return 0;
    }
    let exact = u128::from(part) * 100 / u128::from(total);
    u64::try_from(exact).unwrap_or(u64::MAX)
}
